:root { color-scheme: light; font-family: system-ui, sans-serif; color: #202938; background: #f3f6fa; }
* { box-sizing: border-box; }
body { margin: 0; }
.shell { width: min(760px, calc(100% - 32px)); margin: 56px auto; }
h1 { margin: 0 0 24px; font-size: 2rem; }
.panel { padding: 24px; border: 1px solid #dce3ec; border-radius: 12px; background: white; box-shadow: 0 4px 16px #14263c0a; }
form { display: flex; gap: 12px; align-items: end; }
.field { flex: 1; }
label { display: block; margin-bottom: 7px; font-weight: 600; }
input { width: 100%; min-height: 42px; padding: 9px 11px; border: 1px solid #aeb9c8; border-radius: 6px; font: inherit; }
button { min-height: 42px; padding: 9px 15px; border: 0; border-radius: 6px; background: #2457c5; color: white; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #1946a8; }
button:focus-visible, input:focus-visible { outline: 3px solid #89aaf7; outline-offset: 2px; }
.rows { display: grid; gap: 10px; margin-top: 22px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 12px 14px; border: 1px solid #e0e6ee; border-radius: 8px; }
.project-name { overflow-wrap: anywhere; }
.alert { margin: 14px 0 0; color: #b42318; }
.back { margin-bottom: 20px; background: #46556b; }
.empty { margin: 22px 0 0; color: #647184; }
@media (max-width: 540px) { .shell { margin-top: 28px; } form { align-items: stretch; flex-direction: column; } }
